CREATE EXTENSION IF NOT EXISTS btree_gist;

-- --------------------------------------------------------------------------
CREATE TABLE ai_usage_daily (
  id                         serial NOT NULL,
  user_id                    integer NOT NULL,
  date                       text NOT NULL,
  request_count              integer NOT NULL DEFAULT 0,
  updated_at                 timestamp without time zone NOT NULL DEFAULT now(),
  CONSTRAINT ai_usage_daily_pkey PRIMARY KEY (id),
  CONSTRAINT ai_usage_daily_user_id_date_unique UNIQUE (user_id, date)
);

-- --------------------------------------------------------------------------
CREATE TABLE billing_webhook_notifications (
  stripe_event_id            text NOT NULL,
  event_type                 text NOT NULL,
  status                     text NOT NULL DEFAULT 'pending'::text,
  last_error                 text,
  created_at                 timestamp with time zone NOT NULL DEFAULT now(),
  delivered_at               timestamp with time zone,
  CONSTRAINT billing_webhook_notifications_pkey PRIMARY KEY (stripe_event_id),
  CONSTRAINT billing_webhook_notifications_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'delivered'::text, 'failed'::text])))
);

-- --------------------------------------------------------------------------
CREATE TABLE billing_webhook_notification_recipients (
  id                         bigserial NOT NULL,
  stripe_event_id            text NOT NULL,
  recipient_email            text NOT NULL,
  recipient_name             text NOT NULL,
  company_name               text NOT NULL,
  email_kind                 text NOT NULL,
  trial_ends_at              timestamp with time zone,
  status                     text NOT NULL DEFAULT 'pending'::text,
  attempt_count              integer NOT NULL DEFAULT 0,
  next_attempt_at            timestamp with time zone,
  last_attempt_at            timestamp with time zone,
  delivered_at               timestamp with time zone,
  last_error                 text,
  created_at                 timestamp with time zone NOT NULL DEFAULT now(),
  operator_alerted_at        timestamp with time zone,
  claim_token                text,
  claim_expires_at           timestamp with time zone,
  ambiguous_since            timestamp with time zone,
  CONSTRAINT billing_webhook_notification_recipients_pkey PRIMARY KEY (id),
  CONSTRAINT billing_webhook_notification__stripe_event_id_recipient_ema_key UNIQUE (stripe_event_id, recipient_email),
  CONSTRAINT billing_webhook_notification_recipients_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'delivered'::text, 'failed'::text, 'review'::text])))
);
CREATE INDEX billing_webhook_recipient_retry_due_idx ON public.billing_webhook_notification_recipients USING btree (next_attempt_at, id) WHERE (status = ANY (ARRAY['pending'::text, 'failed'::text, 'processing'::text]));

-- --------------------------------------------------------------------------
CREATE TABLE companies (
  id                         serial NOT NULL,
  name                       text NOT NULL,
  created_at                 timestamp without time zone NOT NULL DEFAULT now(),
  stripe_customer_id         text,
  stripe_subscription_id     text,
  billing_price_id           text,
  billing_plan_key           text,
  billing_seat_quantity      integer,
  billing_trial_ends_at      timestamp without time zone,
  billing_onboarding_completed boolean NOT NULL DEFAULT true,
  CONSTRAINT companies_pkey PRIMARY KEY (id)
);

-- --------------------------------------------------------------------------
CREATE TABLE users (
  id                         serial NOT NULL,
  name                       text NOT NULL,
  email                      text NOT NULL,
  role                       text NOT NULL DEFAULT 'SUPERVISOR'::text,
  phone                      text,
  active                     boolean NOT NULL DEFAULT true,
  created_at                 timestamp without time zone NOT NULL DEFAULT now(),
  updated_at                 timestamp without time zone NOT NULL DEFAULT now(),
  password_hash              text,
  company_id                 integer NOT NULL,
  password_changed_at        timestamp without time zone,
  CONSTRAINT users_pkey PRIMARY KEY (id),
  CONSTRAINT users_email_unique UNIQUE (email)
);

-- --------------------------------------------------------------------------
CREATE TABLE jobs (
  id                         serial NOT NULL,
  name                       text NOT NULL,
  job_number                 text NOT NULL,
  client                     text NOT NULL,
  address                    text NOT NULL,
  status                     text NOT NULL DEFAULT 'active'::text,
  start_date                 date,
  end_date                   date,
  description                text,
  created_at                 timestamp without time zone NOT NULL DEFAULT now(),
  updated_at                 timestamp without time zone NOT NULL DEFAULT now(),
  client_number              text,
  manager_id                 integer,
  supervisor_id              integer,
  dropbox_path               text,
  company_id                 integer NOT NULL,
  client_email               text,
  contact2_name              text,
  contact2_phone             text,
  contact2_email             text,
  CONSTRAINT jobs_pkey PRIMARY KEY (id),
  CONSTRAINT jobs_company_job_number_unique UNIQUE (company_id, job_number)
);

-- --------------------------------------------------------------------------
CREATE TABLE call_forward (
