-- ==========================================================================
-- Trigger functions. These are live business logic, not scaffolding --
-- see docs/contract/domain-rules.md R12.
-- ==========================================================================

CREATE OR REPLACE FUNCTION public.enforce_scheduler_worker_absence_no_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        PERFORM pg_advisory_xact_lock(NEW.company_id, NEW.worker_id);
        IF EXISTS (
          SELECT 1
          FROM scheduler_worker_absences existing
          WHERE existing.company_id = NEW.company_id
            AND existing.worker_id = NEW.worker_id
            AND existing.id <> COALESCE(NEW.id, 0)
            AND daterange(existing.start_date, existing.end_date, '[]')
              && daterange(NEW.start_date, NEW.end_date, '[]')
        ) THEN
          RAISE EXCEPTION 'Worker absence periods cannot overlap'
            USING ERRCODE = '23P01';
        END IF;
        RETURN NEW;
      END;
      $function$;

-- ==========================================================================
-- Triggers
-- ==========================================================================

CREATE TRIGGER scheduler_worker_absences_no_overlap_trigger BEFORE INSERT OR UPDATE OF company_id, worker_id, start_date, end_date ON public.scheduler_worker_absences FOR EACH ROW EXECUTE FUNCTION enforce_scheduler_worker_absence_no_overlap();

